W=/Users/kristinarash/Library/Caches/sportsci-batch-97 && mkdir -p $W/helpers/g1 && cat > $W/helpers/g1/fix_source.py <<'EOF'
import json, sys
W = "/Users/kristinarash/Library/Caches/sportsci-batch-97"
inputs = {p["id"]: p["sourceFile"] for p in json.load(open(W + "/inputs.json", encoding="utf-8"))}
tax = json.load(open(W + "/taxonomy.json", encoding="utf-8"))
allowed = {k: set(v) for k, v in tax.items()}
for pid in ["Q01","Q02","Q03","Q04","Q05","Q06","Q07","Q08"]:
    path = f"{W}/drafts/{pid}.json"
    d = json.load(open(path, encoding="utf-8"))
    d["sourceFile"] = inputs[pid]
    json.dump(d, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    txt = open(path, encoding="utf-8").read()
    flags = []
    if "—" in txt: flags.append("em-dash")
    if d["decision"] == "INCLUDE":
        if d["studyDesign"] not in allowed["studyDesigns"]: flags.append("bad design")
        if d["primaryDomain"] not in allowed["domains"]: flags.append("bad primaryDomain")
        if d["primaryDomain"] not in d["domains"]: flags.append("primary not in domains")
        for f, key in [("domains","domains"),("audiences","audiences"),("sports","sports"),("populations","populations")]:
            for v in d[f]:
                if v not in allowed[key]: flags.append(f"bad {f}: {v}")
    print(pid, d["decision"], d["paper"]["year"] if d["paper"] else "-", "OK" if not flags else flags)
EOF
python3 -I $W/helpers/g1/fix_source.py && ls $W/drafts

